code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
            area = (r1-r0+1) * (c1-c0+1)
            if r1 > r0 and c1 > c0 and area >= 4 and len(cells) >= 3 and len(cells) / area >= 0.5:
                objects.append((color, r0, r1, c0, c1))
    out = [[background] * w for _ in range(h)]
    for color, r0, r1, c0, c1 in objects:
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                out[r][c] = color
    return out
